files.schemas/dashboard/il_steers.schema.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "dashboard/il_steers.schema.json",
  "title": "owner request to the Architect: a steer on an Intent Ledger task (Steer button in the Architect IL pane; the Architect sets status relayed once it has told the PM) or the notice of a task or goal added from the dashboard Add forms (ask_type set; filed_as = the ledger id, dash = the dashboard id; the Architect sets status filed once it has seen it)",
  "type": "object",
  "$defs": {
    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{3})?Z$"},
    "steer": {
      "type": "object",
      "required": ["status", "at", "session", "task", "text", "by"],
      "additionalProperties": false,
      "properties": {
        "status": {"enum": ["new", "relayed"]},
        "at": {"$ref": "#/$defs/iso"},
        "session": {"type": "string", "minLength": 1},
        "task": {"type": "string", "minLength": 1},
        "text": {"type": "string", "minLength": 1},
        "by": {"type": "string"},
        "relayed_at": {"$ref": "#/$defs/iso"}
      }
    },
    "ask": {
      "type": "object",
      "required": ["status", "at", "ask_type", "text", "by", "filed_as", "dash"],
      "additionalProperties": false,
      "properties": {
        "status": {"enum": ["new", "filed"]},
        "at": {"$ref": "#/$defs/iso"},
        "ask_type": {"enum": ["task", "goal"]},
        "text": {"type": "string", "minLength": 1},
        "by": {"type": "string"},
        "filed_as": {"type": "string", "minLength": 1},
        "dash": {"type": "string"},
        "filed_at": {"$ref": "#/$defs/iso"}
      }
    }
  },
  "oneOf": [{"$ref": "#/$defs/steer"}, {"$ref": "#/$defs/ask"}]
}

