files.schemas/dashboard/meta-settings.schema.j:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "dashboard/meta-settings.schema.json",
  "title": "meta/settings (owner presence, sleep window and morning brief)",
  "type": "object",
  "$defs": {
    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{3})?Z$"}
  },
  "additionalProperties": false,
  "properties": {
    "sleep_start": {"type": "string", "pattern": "^[0-9]{2}:[0-9]{2}$"},
    "sleep_end": {"type": "string", "pattern": "^[0-9]{2}:[0-9]{2}$"},
    "tz": {"type": "string", "minLength": 1},
    "user_state": {"enum": ["active", "remote", "mobile", "away", "sleeping"]},
    "technical_level": {"enum": ["non-technical", "vibe-coder", "pm", "engineer", "senior-engineer", "cto"]},
    "user_state_at": {"$ref": "#/$defs/iso"},
    "user_state_by": {"type": "string"},
    "owner_signal_at": {"$ref": "#/$defs/iso"},
    "owner_signal_kind": {"type": "string"},
    "sleep_auto_on": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "morning_brief": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "enabled": {"type": "boolean"},
        "time": {"type": "string", "pattern": "^[0-9]{2}:[0-9]{2}$"},
        "days": {"oneOf": [
          {"enum": ["weekdays", "daily"]},
          {"type": "array", "items": {"enum": ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]}}
        ]},
        "tz": {"type": "string", "minLength": 1}
      }
    },
    "updated": {"$ref": "#/$defs/iso"}
  }
}

files.schemas/dashboard/meta-state.schema.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "dashboard/meta-state.schema.json",
  "title": "meta/state (owner name and fleet usage; next ids are derived, not stored)",
  "type": "object",
  "$defs": {
    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{3})?Z$"}
  },
  "required": ["owner_name", "updated"],
  "additionalProperties": false,
  "properties": {
    "owner_name": {"type": "string", "minLength": 1},
    "updated": {"$ref": "#/$defs/iso"},
    "session_id": {"type": "string", "pattern": "^S[0-9a-km-np-z]{2}$", "description": "S id of the session that owns this store; qualifies ids as <S id>:<local id> (SPEC-IL-01 section 15)"},
    "fleet_usage": {"type": "object", "additionalProperties": false,
                    "properties": {"agents_active": {"type": "integer"}, "agents_parked": {"type": "integer"},
                                   "measured_at": {"$ref": "#/$defs/iso"}, "out_tokens_1h": {"type": "integer"},
                                   "out_tokens_24h": {"type": "integer"}, "units_24h": {"type": "number"}}}
  }
}

files.schemas/dashboard/step_progress.schema.j:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "dashboard/step_progress.schema.json",
  "title": "step progress (owner ticks on an item's steps)",
  "type": "object",
  "$defs": {
    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{3})?Z$"},
    "isoOrEmpty": {"type": "string", "pattern": "^([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{3})?Z)?$"}
  },
  "required": ["item", "updated", "steps"],
  "additionalProperties": false,
  "properties": {
    "item": {"type": "string", "minLength": 1},
    "updated": {"$ref": "#/$defs/iso"},
    "steps": {"type": "object",
              "additionalProperties": {"type": "object", "required": ["done"], "additionalProperties": false,
                                       "properties": {"done": {"type": "boolean"}, "done_at": {"$ref": "#/$defs/isoOrEmpty"},
                                                      "note": {"type": "string"}, "note_at": {"$ref": "#/$defs/iso"}}}}
  }
}

files.schemas/dashboard/watch_changes.schema.j:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "dashboard/watch_changes.schema.json",
  "title": "watch or unwatch request (owner, Projects view); applied by scripts/watch-apply.py through tm fleet project add|remove",
  "type": "object",
  "$defs": {
    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{3})?Z$"}
  },
  "required": ["key", "action", "status", "created", "by"],
  "additionalProperties": false,
  "properties": {
    "key": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$"},
    "action": {"enum": ["watch", "unwatch"]},
    "status": {"enum": ["new", "applied", "failed", "dismissed"]},
    "created": {"$ref": "#/$defs/iso"},
    "by": {"type": "string"},
    "done_at": {"$ref": "#/$defs/iso"},
    "message": {"type": "string"}
  }
}
